-- ============================================================================
-- SIGA-UNMSM · Carga inicial del catálogo nutricional
-- Fuente: Tabla Peruana de Composición de Alimentos - Colegio de Nutricionistas del Perú
-- Generado: 2026-07-24 a partir de AlimentosPeru-3p5g9t__3_.xlsm
--   Hoja 'Alimentos'            -> 928 alimentos base           (tipo BASE_TABLA)
--   Hoja 'Alimentos preparados' -> 942 preparaciones importadas (tipo PREPARADO_IMPORTADO)
--
-- NOTAS IMPORTANTES:
--  1) La hoja 'Alimentos preparados' trae una columna ESTRATO (A-E) por plato;
--     el archivo fuente no define su significado exacto (posible variante
--     regional o socioeconómica). Cada combinación (plato, estrato) se cargó
--     como un alimento independiente, ya que su composición nutricional
--     difiere. Verificar con el nutricionista el significado de "estrato"
--     antes de exponerlo al usuario final.
--  2) La columna "β-caroteno equivalentes totales" que trae la hoja 'Alimentos'
--     NO se cargó: el esquema actual (alimento_version) no tiene esa columna.
--     Si se requiere, se puede agregar con:
--       ALTER TABLE alimento_version ADD COLUMN beta_caroteno_ug DECIMAL(10,3);
--  3) Las celdas sin dato en el archivo original vienen como 0 (no NULL);
--     se cargaron tal cual, respetando fielmente la fuente.
--  4) Se asume que las tablas ya existen (02_modelo_base_datos_v4_mysql.sql
--     ya ejecutado). Este script solo hace INSERT.
-- ============================================================================

